require'json';require'find';require'fileutils';root=File.expand_path('..',__dir__);trees=[root,File.expand_path('../Client',root)];skip=%r{/(?:\.git|target|build|work|logs|node_modules|temp|library)(?:/|$)}i;non_nfc=[];collisions=[];count=0;trees.each{|tree|normalized=Hash.new{|h,k|h[k]=[]};Find.find(tree){|p|if File.directory?(p)&&p!=tree&&p.match?(skip);Find.prune;next;end;next if p==tree;count+=1;rel=p.delete_prefix(tree+'/');nfc=rel.unicode_normalize(:nfc);non_nfc<<rel if rel!=nfc;normalized[nfc]<<rel};collisions.concat(normalized.values.select{|rows|rows.uniq.length>1})};result={task:'FS03',passed:non_nfc.empty?&&collisions.empty?,scannedPaths:count,nonNfcPaths:non_nfc.sort,normalizedCollisions:collisions.sort};out=File.join(root,'docs/generated/fs03-unicode-normalization.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");abort("FS03 normalization violations=#{non_nfc.length}, collisions=#{collisions.length}")unless result[:passed]
